INSERT INTO lecture_courses (id, specialty_id, department_id, name, description, semester, total_hours, lecture_hours, practice_hours, lab_hours, is_elective, tags) VALUES
('bc42be9c-5a5e-5b9c-acb7-60407fd6b350', 'aea4aef1-eafb-5e64-9e7c-d91c531cf987', '0bc8df6b-96de-57cb-b78c-8c0b99c590dc', 'Проектирование архитектуры ПО', 'Курс посвящён проектированию архитектуры программных систем: монолитной и микросервисной архитектуре, шлюзам API, нотациям C4 и DFD, полиглотному хранению данных и масштабированию. Студенты проектируют систему из нескольких сервисов и обосновывают выбор хранилищ.', 6, 144, 32, 16, 32, FALSE, ARRAY['спецдисциплина кафедры']::text[]),
('2853dadd-f264-587f-9556-ac6b8eb35d47', 'aea4aef1-eafb-5e64-9e7c-d91c531cf987', '0bc8df6b-96de-57cb-b78c-8c0b99c590dc', 'Большие данные и потоковая обработка', 'Изучаются пакетная и потоковая обработка больших данных, брокер сообщений Kafka, захват изменений данных (CDC) и партиционирование таблиц и топиков. Рассматриваются задержка, пропускная способность и гарантии доставки.', 6, 108, 32, 0, 32, FALSE, ARRAY['спецдисциплина кафедры']::text[]),
('7fd34c76-ca4b-5235-accc-545e52ff1630', 'aea4aef1-eafb-5e64-9e7c-d91c531cf987', '0bc8df6b-96de-57cb-b78c-8c0b99c590dc', 'Распределённые системы', 'Рассматриваются модели консистентности, репликация и кворумы, теорема CAP, распределённые транзакции и очереди сообщений. Разбираются отказы узлов и сетевые разделения.', 6, 108, 32, 16, 0, FALSE, ARRAY['спецдисциплина кафедры']::text[]),
('c0e3c98c-7340-5c61-bdc0-62ffd12703cf', 'aea4aef1-eafb-5e64-9e7c-d91c531cf987', '0bc8df6b-96de-57cb-b78c-8c0b99c590dc', 'Хранилища данных и OLAP', 'Курс о построении корпоративных хранилищ данных: схемы «звезда» и «снежинка», многомерные кубы OLAP, загрузка ETL и медленно меняющиеся измерения.', 6, 108, 32, 16, 0, FALSE, ARRAY['спецдисциплина кафедры']::text[]),
('0595cd57-891b-5f79-a6be-cf2d1a94b1e8', 'aea4aef1-eafb-5e64-9e7c-d91c531cf987', '0bc8df6b-96de-57cb-b78c-8c0b99c590dc', 'Информационная безопасность', 'Основы защиты информационных систем: аутентификация и авторизация, токены JWT, шифрование данных, сегментация сети и демилитаризованная зона.', 6, 72, 16, 16, 0, FALSE, '{}'::text[]),
('7c6ff099-7f7e-5949-9b0e-47d6eaeb925f', 'aea4aef1-eafb-5e64-9e7c-d91c531cf987', '0bc8df6b-96de-57cb-b78c-8c0b99c590dc', 'NoSQL и полиглотное хранение', 'Курс по выбору о нереляционных базах данных: хранилища ключ-значение (Redis), документные (MongoDB), графовые (Neo4j) и поисковые (Elasticsearch). Разбирается, как разместить данные одной системы в нескольких хранилищах по принципу полиглотного хранения.', 6, 72, 16, 0, 16, TRUE, ARRAY['спецдисциплина кафедры', 'курс по выбору']::text[]),
('6f844249-f144-52c9-96d7-bf679eec52d0', 'aea4aef1-eafb-5e64-9e7c-d91c531cf987', '0bc8df6b-96de-57cb-b78c-8c0b99c590dc', 'Бизнес-аналитика', 'Курс по выбору о методах бизнес-аналитики: ключевые показатели эффективности, построение дашбордов, метрики продукта и визуализация данных для принятия решений.', 6, 72, 16, 16, 0, TRUE, ARRAY['курс по выбору']::text[]),
('6adf1b73-e8ae-568b-8aeb-32c581454a0c', 'df0015bb-290e-567b-903f-b6ac17508e1f', '50c128a8-fc87-5405-b499-8b20fa282397', 'Проектирование архитектуры ПО', 'Принципы проектирования архитектуры программных систем: монолит и микросервисы, шлюз API, нотации C4 и DFD, выбор хранилищ данных.', 6, 144, 32, 16, 32, FALSE, ARRAY['спецдисциплина кафедры']::text[]),
('89702963-877e-5fcd-82ac-bc03791bb4b1', 'df0015bb-290e-567b-903f-b6ac17508e1f', '50c128a8-fc87-5405-b499-8b20fa282397', 'Тестирование программного обеспечения', 'Методы и уровни тестирования программ, автоматизация тестирования, непрерывная интеграция и метрики покрытия.', 6, 108, 32, 0, 32, FALSE, ARRAY['спецдисциплина кафедры']::text[]),
('868a3c59-cb18-5bb6-a253-34728a81086c', 'df0015bb-290e-567b-903f-b6ac17508e1f', '50c128a8-fc87-5405-b499-8b20fa282397', 'Компьютерные сети', 'Стек протоколов TCP/IP, адресация и маршрутизация, прикладные протоколы и сегментация сетей.', 6, 108, 32, 16, 0, FALSE, '{}'::text[]),
('9b1402a1-ca94-5d53-8cf1-6e6dd0b2e6c3', 'df0015bb-290e-567b-903f-b6ac17508e1f', '50c128a8-fc87-5405-b499-8b20fa282397', 'Машинное обучение', 'Курс по выбору: постановка задач машинного обучения, модели регрессии и классификации, оценка качества.', 6, 72, 16, 0, 16, TRUE, ARRAY['курс по выбору']::text[]),
('1f80b915-4f31-535a-ad9b-e7f3d8c8cde4', 'df0015bb-290e-567b-903f-b6ac17508e1f', '50c128a8-fc87-5405-b499-8b20fa282397', 'Разработка мобильных приложений', 'Курс по выбору: архитектура мобильного приложения, работа с сетью и локальным хранилищем.', 6, 72, 16, 0, 16, TRUE, ARRAY['курс по выбору']::text[]);
