INSERT INTO lecture_materials (id, lecture_id, content_type, title, content_text, file_url, metadata) VALUES
('0d96c5d0-d669-594a-a69b-7e14b6b7c726', 'e05b7bf6-5342-5886-8a69-e4c9cf9824cb', 'text', 'Конспект: Введение в дисциплину «Проектирование архитектуры ПО»', 'Студенты учатся проектировать компоненты с учётом требований к «микросервис». Приводятся практические примеры применения подхода «API Gateway» в корпоративной среде. На занятии рассматривается понятие «микросервис» и его роль в современных информационных системах.', NULL, '{}'),
('e86de9a1-c1fe-5b2e-82a4-26a83016d881', 'e05b7bf6-5342-5886-8a69-e4c9cf9824cb', 'presentation', 'Слайды к занятию 1', NULL, '/files/bc42be9c/lecture_01.pdf', '{"file_size_mb": 3.8, "pages": 40}'),
('5c9ca653-dfe0-5f20-9cd2-d8f212b9ef40', '116850d7-76d4-50e9-8112-a3f9d49ad938', 'text', 'Конспект: Практическое занятие: монолит', 'Приводятся практические примеры применения подхода «монолит» в корпоративной среде. Приводятся практические примеры применения подхода «монолит» в корпоративной среде. Приводятся практические примеры применения подхода «API Gateway» в корпоративной среде.', NULL, '{}'),
('f7ce2d11-c530-55b0-b27c-9e04445e0314', '116850d7-76d4-50e9-8112-a3f9d49ad938', 'exercise', 'Вопросы для самопроверки', NULL, NULL, '{"questions": [{"q": "Что такое «монолит»?", "difficulty": "easy"}, {"q": "Когда применять «монолит» и когда нет?", "difficulty": "medium"}]}'),
('e7f830b9-bf1a-50f5-868d-affdabcde0fe', 'a25c08ca-2ad6-5b60-8198-9b92e2c07d12', 'text', 'Конспект: Практическое занятие: API Gateway', 'На занятии рассматривается понятие «API Gateway» и его роль в современных информационных системах. На занятии рассматривается понятие «C4» и его роль в современных информационных системах. Рассматривается связь темы «монолит» с дисциплиной «Проектирование архитектуры ПО» и смежными разделами.', NULL, '{}'),
('86e82fa0-3d8e-5c59-bb9d-83769445bf67', 'a25c08ca-2ad6-5b60-8198-9b92e2c07d12', 'exercise', 'Вопросы для самопроверки', NULL, NULL, '{"questions": [{"q": "Что такое «API Gateway»?", "difficulty": "easy"}, {"q": "Когда применять «API Gateway» и когда нет?", "difficulty": "medium"}]}'),
('c5e19479-397c-54ae-b788-102b2d5d4a3d', '6dec7b93-4ed4-58f5-9a6e-e089fb647fed', 'text', 'Конспект: C4: принципы и применение', 'На занятии рассматривается понятие «C4» и его роль в современных информационных системах. Обсуждаются достоинства и ограничения, связанные с использованием «монолит». Приводятся практические примеры применения подхода «масштабирование» в корпоративной среде.', NULL, '{}'),
('a19c0d36-dabe-5274-9b0e-53e220ab748a', '6dec7b93-4ed4-58f5-9a6e-e089fb647fed', 'presentation', 'Слайды к занятию 4', NULL, '/files/bc42be9c/lecture_04.pdf', '{"file_size_mb": 2.6, "pages": 48}'),
('a134668b-12a8-5c09-a6bb-c9751384f2ee', '6dec7b93-4ed4-58f5-9a6e-e089fb647fed', 'exercise', 'Вопросы для самопроверки', NULL, NULL, '{"questions": [{"q": "Что такое «C4»?", "difficulty": "easy"}, {"q": "Когда применять «C4» и когда нет?", "difficulty": "medium"}]}'),
('e0e8bde6-2e20-593e-b2dc-b471a3b7bcf1', '0cacfe3e-c438-57b7-ae17-7f43f2eb61c0', 'text', 'Конспект: Практическое занятие: DFD', 'Подробно разбирается, как DFD влияет на архитектуру и производительность решения. На занятии рассматривается понятие «монолит» и его роль в современных информационных системах. Подробно разбирается, как масштабирование влияет на архитектуру и производительность решения.', NULL, '{}'),
('8437fb1b-d1ff-5842-972a-077313e68e51', '0cacfe3e-c438-57b7-ae17-7f43f2eb61c0', 'exercise', 'Вопросы для самопроверки', NULL, NULL, '{"questions": [{"q": "Что такое «DFD»?", "difficulty": "easy"}, {"q": "Когда применять «DFD» и когда нет?", "difficulty": "medium"}]}'),
('fa6936c6-cca5-52eb-8294-d8832f58ea7c', '583e96ab-b530-5c7f-8c95-347b76ea8fbd', 'text', 'Конспект: Масштабирование: принципы и применение', 'Рассматривается связь темы «масштабирование» с дисциплиной «Проектирование архитектуры ПО» и смежными разделами. Обсуждаются достоинства и ограничения, связанные с использованием «API Gateway». Подробно разбирается, как масштабирование влияет на архитектуру и производительность решения.', NULL, '{}'),
